diff --git a/plasmoid/TabletModeItem.qml b/plasmoid/TabletModeItem.qml
new file mode 100644
index 00000000..66dae7aa
--- /dev/null
+++ b/plasmoid/TabletModeItem.qml
@@ -0,0 +1,43 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-only OR GPL-3.0-only OR LicenseRef-KDE-Accepted-GPL
+*/
+
+pragma ComponentBehavior: Bound
+
+import QtQuick
+import QtQuick.Layouts
+
+import org.kde.kirigami as Kirigami
+import org.kde.plasma.components as PlasmaComponents3
+import org.kde.plasma.extras as PlasmaExtras
+import org.kde.plasma.plasmoid
+
+ColumnLayout {
+    id: root
+
+    spacing: Kirigami.Units.smallSpacing
+
+    PlasmaComponents3.Switch {
+        id: tabletModeSwitch
+        Layout.fillWidth: true
+        // Remove spacing between checkbox and the explanatory label below
+        Layout.bottomMargin: -root.spacing
+        text: i18n("Enable Tablet Mode")
+
+        onToggled: Plasmoid.setTabletModeEnabled(checked) // qmllint disable missing-property
+
+        Binding on checked {
+            value: Kirigami.Settings.tabletMode
+        }
+    }
+
+    PlasmaExtras.DescriptiveLabel {
+        Layout.fillWidth: true
+        Layout.leftMargin: tabletModeSwitch.indicator.width + tabletModeSwitch.spacing
+        font: Kirigami.Theme.smallFont
+        text: i18n("In Tablet Mode, the on-screen keyboard will appear when needed.")
+        wrapMode: Text.WordWrap
+    }
+}
diff --git a/plasmoid/kscreenapplet.cpp b/plasmoid/kscreenapplet.cpp
index b48b785d..d236c435 100644
--- a/plasmoid/kscreenapplet.cpp
+++ b/plasmoid/kscreenapplet.cpp
@@ -7,6 +7,9 @@

 #include "kscreenapplet.h"

+#include <KConfigGroup>
+#include <KSharedConfig>
+
 #include <QMetaEnum>
 #include <QQmlEngine> // for qmlRegisterType

@@ -41,6 +44,10 @@ void KScreenApplet::init()

                 checkOutputs();
             });
+
+    m_kwinConfigWatcher = KConfigWatcher::create(KSharedConfig::openConfig(QStringLiteral("kwinrc")));
+    connect(m_kwinConfigWatcher.data(), &KConfigWatcher::configChanged, this, &KScreenApplet::checkTabletMode);
+    checkTabletMode();
 }

 int KScreenApplet::connectedOutputCount() const
@@ -53,6 +60,28 @@ void KScreenApplet::applyLayoutPreset(KScreen::OsdAction::Action action)
     KScreen::OsdAction::applyAction(m_screenConfiguration, action);
 }

+bool KScreenApplet::isTabletModeForced() const
+{
+    return m_tabletModeForced;
+}
+
+void KScreenApplet::setTabletModeEnabled(bool enabled)
+{
+    KConfigGroup group = m_kwinConfigWatcher->config()->group(QStringLiteral("Input"));
+    group.writeEntry("TabletMode", enabled ? QStringLiteral("on") : QStringLiteral("off"), KConfig::Notify);
+    group.sync();
+}
+
+void KScreenApplet::checkTabletMode()
+{
+    const KConfigGroup group = m_kwinConfigWatcher->config()->group(QStringLiteral("Input"));
+    const bool forced = group.readEntry("TabletMode", QStringLiteral("auto")) != QLatin1String("auto");
+    if (m_tabletModeForced != forced) {
+        m_tabletModeForced = forced;
+        Q_EMIT tabletModeForcedChanged();
+    }
+}
+
 void KScreenApplet::checkOutputs()
 {
     if (!m_screenConfiguration) {
